// RFC 9110 §4.2.1: "A sender MUST NOT generate an "http" URI with an empty host identifier. A recipient that processes
// such a URI reference MUST reject it as invalid." The same for https (§4.2.2). An IP literal is only its shape here, like
// in the generic patterns, which leave checking it to ipLiteralPattern.
export const httpHost = /\u{5B}[^\u{23}\u{25}\u{2F}\u{3F}\u{5B}-\u{5D}]*\u{5D}|[^\u{23}\u{2F}\u{3A}\u{3F}\u{5B}-\u{5D}]+/u;

// RFC 8089 §2: auth-path = [ file-auth ] path-absolute, and local-path = path-absolute
export const filePath = /\u{2F}(?!\u{2F})[^\u{23}\u{3F}]*/u;

// RFC 8141 §2: assigned-name = "urn" ":" NID ":" NSS. A URN is ASCII in an IRI too: RFC 8141 "does not extend the URN
// syntax to allow direct use of characters outside the ASCII range".
export const urnPath = /[0-9A-Za-z][\u{2D}0-9A-Za-z]{0,30}[0-9A-Za-z]\u{3A}[^\u{23}\u{2F}\u{3F}\u{7F}-\u{10FFFF}][^\u{23}\u{3F}\u{7F}-\u{10FFFF}]*/u;

// RFC 8141 §2: rq-components = [ "?+" r-component ] [ "?=" q-component ], which starts with the query's delimiter, so
// it's written for what's after the "?"
export const urnQuery = /\u{2B}[^\u{23}\u{2F}\u{3F}\u{7F}-\u{10FFFF}][^\u{23}\u{7F}-\u{10FFFF}]*(?:\u{3F}\u{3D}[^\u{23}\u{2F}\u{3F}\u{7F}-\u{10FFFF}][^\u{23}\u{7F}-\u{10FFFF}]*)?|\u{3D}[^\u{23}\u{2F}\u{3F}\u{7F}-\u{10FFFF}][^\u{23}\u{7F}-\u{10FFFF}]*/u;

// RFC 8141 §2: f-component = fragment
export const urnFragment = /[^\u{7F}-\u{10FFFF}]*/u;

// DID 1.1 §3.2: did-url = did path-abempty [ "?" query ] [ "#" fragment ], where did = "did:" method-name ":"
// method-specific-id. Every rule is ASCII, so a DID is ASCII in an IRI too.
export const didPath = /[0-9a-z]+\u{3A}(?:[\u{25}\u{2D}\u{2E}0-9A-z]*\u{3A})*[\u{25}\u{2D}\u{2E}0-9A-z]+(?![^\u{23}\u{2F}\u{3F}\u{7F}-\u{10FFFF}])[^\u{23}\u{3F}\u{7F}-\u{10FFFF}]*/u;

// DID 1.1 §3.2: a DID URL's query is RFC 3986's, which is ASCII
export const didQuery = /[^\u{23}\u{7F}-\u{10FFFF}]*/u;

// DID 1.1 §3.2: a DID URL's fragment is RFC 3986's, which is ASCII
export const didFragment = /[^\u{7F}-\u{10FFFF}]*/u;

// RFC 9562 §4, verbatim
export const uuidNss = /(?:[0-9A-Fa-f][0-9A-Fa-f]){4}\u{2D}(?:[0-9A-Fa-f][0-9A-Fa-f]){2}\u{2D}(?:[0-9A-Fa-f][0-9A-Fa-f]){2}\u{2D}(?:[0-9A-Fa-f][0-9A-Fa-f]){2}\u{2D}(?:[0-9A-Fa-f][0-9A-Fa-f]){6}/u;
